import java.util.ArrayList;
import java.util.List;
import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        while (scanner.hasNextLong()) {
            long n = scanner.nextLong();
            int k = scanner.nextInt();

            List<Long> state = new ArrayList<>();
            for (int i = 0; i < k + 3; i++) {
                state.add(0L);
            }
            state.set(k, 1L);
            state.set(k + 1, 1L);
            state.set(k + 2, 1L);

            long base = 1;
            int count_digits = 0;
            while (base <= n / k) {
                base *= k;
                count_digits++;
            }

            List<List<Long>> matrices = new ArrayList<>();
            for (int i = 0; i <= count_digits; i++) {
                List<Long> row = new ArrayList<>();
                for (int j = 0; j < k + 3; j++) {
                    row.add(0L);
                }
                matrices.add(row);
            }

            // Initialize matrices[0]
            for (int i = 0; i < k; i++) {
                matrices.get(0).set(i, 0L);
            }
            matrices.get(0).set(k, 1L);
            matrices.get(0).set(k + 1, 1L);
            matrices.get(0).set(k + 2, 1L);

            long offset = 0;
            int digit_idx = count_digits;
            while (base > 0) {
                int t = (int)((n - offset) / base);
                for (int j = 0; j < t; j++) {
                    int s = 0; // simplified
                    for (int i = 0; i < k; i++) {
                        long current = state.get(i);
                        state.set(i, current + s);
                    }
                    offset += base;
                }
                base /= k;
                digit_idx--;
            }
            System.out.println(state.get(k + 1));
        }
        scanner.close();
    }
}
